const GRID_COLS = 4;
const CATALOG_IDS = new Set(['weather', 'calendar', 'spotify']);
const req = $('Webhook').item.json.body;
let widgets;
try {
  widgets = JSON.parse($json.widget_json ?? '[]');
  if (!Array.isArray(widgets)) widgets = [];
} catch (e) {
  widgets = [];
}

function clampWidget(w) {
  const x = Math.max(0, Math.min(GRID_COLS - 1, Math.round(w.x ?? 0)));
  const w2 = Math.max(1, Math.min(GRID_COLS - x, Math.round(w.w ?? 1)));
  const y = Math.max(0, Math.round(w.y ?? 0));
  const h = Math.max(1, Math.round(w.h ?? 1));
  return { type: w.type, x, y, w: w2, h, data: w.data ?? null };
}

let fetchNeeded = false;
let error = null;

if (req.action === 'show') {
  if (!CATALOG_IDS.has(req.type)) {
    error = `Unknown widget type '${req.type}'.`;
  } else if (!widgets.some(w => w.type === req.type)) {
    widgets.push(clampWidget({ type: req.type, x: 0, y: widgets.length, w: 1, h: 1, data: null }));
    fetchNeeded = true;
  }
} else if (req.action === 'hide') {
  widgets = widgets.filter(w => w.type !== req.type);
} else if (req.action === 'move' || req.action === 'resize') {
  // A real bug caught in testing: silently no-opping here (matching
  // an id with .map that finds nothing) returned success with the
  // layout unchanged, and the LLM confidently reported a move that
  // never happened. Erroring explicitly instead when the target
  // isn't currently shown.
  if (!widgets.some(w => w.type === req.type)) {
    error = `'${req.type}' is not currently shown on the dashboard - use action='show' first.`;
  } else if (req.action === 'move') {
    widgets = widgets.map(w => (w.type === req.type ? clampWidget({ ...w, x: req.x, y: req.y }) : w));
  } else {
    widgets = widgets.map(w => (w.type === req.type ? clampWidget({ ...w, w: req.w, h: req.h }) : w));
  }
}
// action === 'get_layout' falls through with widgets unchanged.

return [{ json: { widgets, fetchNeeded, error, reasoning: '' } }];

// Merge freshly-fetched data into whichever widget 'show' just
// added (fetchNeeded true) - only relevant on that path.
const state = $('Apply Change').item.json;
let widgets = state.widgets;
if (state.fetchNeeded) {
  const data = $json;
  widgets = widgets.map(w => (w.data === null ? { ...w, data: data[w.type] ?? null } : w));
}
return [{ json: { widgets, error: state.error, reasoning: state.reasoning } }];
